#[no_mangle]
pub unsafe extern "C" fn baileys_client_forward_message(
    handle: *mut BaileysClientHandle,
    to_jid: *const c_char,
    message_id: *const c_char,
) -> *mut c_char {
    let Some(h) = handle_ref(handle) else {
        return std::ptr::null_mut();
    };
    let to_jid = match cstr_opt(to_jid) {
        Some(Some(v)) => v,
        _ => {
            invalid_arg("to_jid");
            return std::ptr::null_mut();
        }
    };
    let message_id = match cstr_opt(message_id) {
        Some(Some(v)) => v,
        _ => {
            invalid_arg("message_id");
            return std::ptr::null_mut();
        }
    };
    let c = h.client.clone();
    let res = h.runtime.block_on(async move {
        {
            match c
                .get_recent_message(&message_id)
                .await
                .and_then(|m| m.message)
            {
                Some(m) => c.forward_message(&to_jid, m, true, 1).await,
                None => {
                    use prost::Message as _;
                    match c.store.get_message(&message_id).await {
                        Ok(Some(s)) => match baileys_core::baileys_proto::proto::Message::decode(
                            s.proto_bytes.as_slice(),
                        ) {
                            Ok(m) => c.forward_message(&to_jid, m, true, 1).await,
                            Err(e) => Err(baileys_core::CoreError::Protocol(e.to_string())),
                        },
                        Ok(None) => Err(baileys_core::CoreError::Protocol(format!(
                            "message {message_id} not found"
                        ))),
                        Err(e) => Err(baileys_core::CoreError::Store(e.to_string())),
                    }
                }
            }
        }
    });
    finish_str(res)
}

