#[no_mangle]
pub unsafe extern "C" fn baileys_client_product_create(
    handle: *mut BaileysClientHandle,
    product: *const c_char,
) -> *mut c_char {
    let Some(h) = handle_ref(handle) else {
        return std::ptr::null_mut();
    };
    let product: baileys_core::CatalogProduct = match cstr_opt(product) {
        Some(Some(j)) => match serde_json::from_str(&j) {
            Ok(v) => v,
            Err(e) => {
                set_last_error(format!("product: {e}"));
                return std::ptr::null_mut();
            }
        },
        _ => {
            invalid_arg("product");
            return std::ptr::null_mut();
        }
    };
    let c = h.client.clone();
    let res = h
        .runtime
        .block_on(async move { c.product_create(&product).await });
    finish_str(res)
}

